/* Common Mandarin readings without tone marks, for U+4E00 through U+9FFF. */
const SYLLABLES = "yi,ding,kao,qi,shang,xia,han,wan,zhang,san,ji,bu,yu,mian,gai,chou,zhuan,qie,pi,shi,qiu,bing,ye,cong,dong,si,cheng,diu,liang,you,yan,sang,gun,jiu,ge,ya,qiang,zhong,jie,feng,guan,chuan,chan,lin,zhuo,zhu,ba,dan,wei,jing,li,ju,pie,fu,nai,wu,tuo,me,zhi,zha,hu,fa,le,yin,ping,pang,qiao,guai,mie,xi,xiang,shu,dou,nang,jia,mao,mai,luan,zi,ru,xue,sha,na,gan,suo,zhe,qian,gui,jue,zheng,er,chu,kui,yun,sui,gen,xie,tou,wang,kang,da,jiao,hai,heng,mu,ting,qin,bo,lian,duo,ren,shen,ze,jin,pu,reng,fo,lun,cang,zai,ta,xian,hong,tong,dai,ling,chao,chang,sa,men,fan,yang,wo,jian,yao,fen,di,fang,pei,diao,dun,xin,ai,xiu,tang,huo,hui,cui,che,xun,chi,nu,gu,ni,ban,xu,zhou,qu,ci,beng,ga,dian,bi,zhao,zuo,ti,zhan,he,she,gou,ning,yong,wa,ka,bao,lao,bai,ming,hen,quan,tiao,xing,kan,lai,kua,guang,mi,an,lu,mou,cha,gong,cun,lv,zhen,ce,kuai,chai,nong,hou,jiong,tui,nan,xiao,bian,cu,e,ku,jun,zu,hun,su,lia,pai,biao,fei,bei,zong,tian,dao,tan,chui,peng,kong,juan,luo,song,leng,ben,cai,zhai,qing,ying,ruan,chun,ruo,pian,sheng,huang,duan,ou,za,lou,sou,yuan,rong,jiang,ma,bang,hao,shan,bin,nuo,can,lei,zao,ao,chuang,piao,man,zun,liao,tie,seng,min,sai,dang,xuan,tai,lan,meng,qiong,lie,kuang,zan,chen,teng,long,rang,xiong,chong,dui,ke,tu,nei,liu,shou,ran,gang,gua,kou,pan,qia,mei,zhun,cou,du,kai,deng,wen,hua,yue,bie,pao,geng,shua,cuo,la,pou,tuan,mo,keng,shao,gao,lang,weng,tao,nao,zang,suan,nian,shuai,ang,que,zui,rou,shuang,die,rui,po,mang,tun,fou,shun,guo,pen,ne,m,huai,pin,ha,yo,o,shuo,huan,nou,ken,a,chuai,pa,se,nie,wai,miao,n,cao,de,hei,ceng,ca,chuo,zeng,nin,kun,qun,ri,lve,zhui,hang,sao,zhuang,en,zou,nv,nuan,niu,rao,niang,niao,nen,sun,kuan,cen,cuan,shui,kuo,te,zen,re,zei,den,zhua,shuan,zhuai,rua,zuan,shai,sen,run,chua,tunwa,nve,gei,neng,fiao,ei,miu,eng,nun".split(",");
const PACK = "";
let table: Uint8Array | undefined;

function readings() {
  if (table) return table;
  const decode = (globalThis as { atob?: (data: string) => string }).atob;
  if (!decode) throw new Error("Base64 decoder is unavailable");
  table = Uint8Array.from(decode(PACK), char => char.charCodeAt(0));
  return table;
}

export function pinyinOf(char: string) {
  const code = char.codePointAt(0);
  if (code == null || code < 0x4e00 || code > 0x9fff) return null;
  const bytes = readings();
  const offset = (code - 0x4e00) * 2;
  const index = bytes[offset] | (bytes[offset + 1] << 8);
  return index ? SYLLABLES[index - 1] : null;
}
